async function saveTenantConfig(env: Env, config: TenantSandboxConfig): Promise<void> {
  const validation = validateTenantSystemPrompt(config.customSystemPrompt);
  if (!validation.valid) throw new Error(`Invalid system prompt: ${validation.errors.join(', ')}`);
  config.updatedAt = new Date().toISOString();
  await env.TENANT_CONFIG.put(`tenant:${config.tenantId}`, JSON.stringify(config));
}

